(function () {
  function request(el) {
    var method = (el.getAttribute("hx-post") ? "POST" : "GET");
    var url = el.getAttribute("hx-post") || el.getAttribute("hx-get");
    var target = document.querySelector(el.getAttribute("hx-target") || "");
    if (!url) return;
    fetch(url, { method: method })
      .then(function (response) {
        var type = response.headers.get("content-type") || "";
        return type.indexOf("application/json") >= 0 ? response.json() : response.text();
      })
      .then(function (body) {
        if (!target) return;
        target.innerHTML = typeof body === "string" ? body : JSON.stringify(body, null, 2);
      });
  }

  function wire() {
    document.querySelectorAll("[hx-get],[hx-post]").forEach(function (el) {
      if (el.dataset.htmxLiteBound) return;
      el.dataset.htmxLiteBound = "1";
      var trigger = el.getAttribute("hx-trigger") || "click";
      if (trigger.indexOf("load") >= 0) request(el);
      var every = trigger.match(/every\s+(\d+)s/);
      if (every) window.setInterval(function () { request(el); }, Number(every[1]) * 1000);
      if (trigger.indexOf("click") >= 0 || el.tagName === "BUTTON") {
        el.addEventListener("click", function (event) {
          event.preventDefault();
          request(el);
        });
      }
    });
  }

  document.addEventListener("DOMContentLoaded", wire);
})();
